    virtual std::shared_ptr<FocusRulesCheckNode> GetAceParent();
    virtual bool IsAccessibiltyVisible();
    virtual bool IsChildTreeContainer();
    virtual bool IsEmbededTarget();
    // ... 更多检查方法
};
